function validate([s, t]) {
  if (typeof s !== 'string' || typeof t !== 'string') return 's and t must be strings.';
  if (s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 digits.';
  if (t.length !== s.length) return 's and t must have the same length.';
  if (!/^[0-9]+$/.test(s) || !/^[0-9]+$/.test(t)) return 's and t may contain only digits.';
  return null;
}

