function isTransformable(s, t) {
  const positions = Array.from({ length: 10 }, () => []);
  for (let i = 0; i < s.length; i++) {
    positions[Number(s[i])].push(i);
  }
  const heads = new Array(10).fill(0);

  for (const ch of t) {
    const digit = Number(ch);
    if (heads[digit] === positions[digit].length) {
      return false;
    }
    const index = positions[digit][heads[digit]];
    for (let smaller = 0; smaller < digit; smaller++) {
      if (heads[smaller] < positions[smaller].length && positions[smaller][heads[smaller]] < index) {
        return false;
      }
    }
    heads[digit]++;
  }
  return true;
}

