function isTransformable(s, t) {
  // Breadth-first search over every string reachable by sorting any substring.
  const seen = new Set([s]);
  const queue = [s];
  for (let q = 0; q < queue.length; q++) {
    const current = queue[q];
    if (current === t) return true;
    for (let i = 0; i < current.length; i++) {
      for (let j = i + 2; j <= current.length; j++) {
        const next = current.slice(0, i) + current.slice(i, j).split('').sort().join('') + current.slice(j);
        if (!seen.has(next)) { seen.add(next); queue.push(next); }
      }
    }
  }
  return false;
}

