function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 6);
  const span = size === 'large' ? 10 : 2 + Math.floor(rand() * 3);
  const digits = Array.from({ length: n }, () => Math.floor(rand() * span));
  const s = digits.join('');
  const mode = rand();
  if (mode < 0.2) {
    // Any string of the same length: usually the digit counts differ.
    return [s, Array.from({ length: n }, () => Math.floor(rand() * span)).join('')];
  }
  if (mode < 0.4) {
    // A random rearrangement of s.
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [digits[i], digits[j]] = [digits[j], digits[i]];
    }
    return [s, digits.join('')];
  }
  // Apply a few real sort operations, so t is reachable...
  const ops = 1 + Math.floor(rand() * 5);
  for (let k = 0; k < ops; k++) {
    const i = Math.floor(rand() * n), j = i + Math.floor(rand() * (n - i));
    const part = digits.slice(i, j + 1).sort((a, b) => a - b);
    for (let p = 0; p < part.length; p++) digits[i + p] = part[p];
  }
  // ...and sometimes swap one neighbouring pair afterwards, which may or may not stay reachable.
  if (mode > 0.7 && n > 1) {
    const i = Math.floor(rand() * (n - 1));
    [digits[i], digits[i + 1]] = [digits[i + 1], digits[i]];
  }
  return [s, digits.join('')];
}
